solution.sanitized:
def markdown_titles(text):
    import re
    out, fenced = [], False
    for line in text.splitlines():
        if line.startswith("```"):
            fenced = not fenced
            continue
        if not fenced:
            match = re.fullmatch(r"(#{1,6}) (.*)", line)
            if match:
                out.append((len(match[1]), match[2]))
    return out

